sys_ui_page.client_script:
/*******************************************************************************************************************************************************
  Author : Saurabh Mehta
  Description : UI Page script from generating a dashboard for incident creation. 
--------------------------------------------------------------------------------------------------------------------------------------------------------
  VERSION     ISSUE-NUMBER             DATE              AUTHOR                      DETAILS                                                           
   1.            -                     24-08-2019        Aman Jaiswal    
   2.                                  24-03-2023        Saurabh Mehta
*******************************************************************************************************************************************************/

var app = angular.module('pageLoad', []);
app.controller('pageLoadCtrl',function($scope) {
	var dateConvertionFields = ["lastRun","maxGeneratedOn"];
	var labelChangedFields = {"lastRun":"Last Sync Time","failureNumberSinceLastSuccess":"Number of failed attempts to open a ticket","maxGeneratedOn":"Next Sync time","isActive":"Status"};
	var priorityMapping = ["urgency","severity","impact"];
	var priority = [
		{
			"value": 1,
			"name": "High"
		}, {
			"value": 2,
			"name": "Medium"
		}, {
			"value": 3,
			"name": "Low"
		}]; 
	$scope.incidentConfigData = {};
	$scope.schedulerData ={};

	$scope.onload = function(response) {
		if(response!==undefined){
			var label=[];
			var graphData=[];
			var answer = response.responseXML.documentElement.getAttribute("answer");
			if(answer!==undefined && answer!=null){
				var data = JSON.parse(answer);
				data.forEach(function(map) {
					switch(map.type){
						case "scheduler":
							if(dateConvertionFields.indexOf(map["key"])>=0 && map.value!="" && labelChangedFields[map["key"]]){
								$scope.schedulerData[labelChangedFields[map["key"]].split(/(?=[A-Z])/).join(" ")] = moment.utc(map.value).format('YYYY-MM-DD HH:mm');
							}
							else{
								if(labelChangedFields[map["key"]]){
									$scope.schedulerData[labelChangedFields[map["key"]].split(/(?=[A-Z])/).join(" ")] = map.value;
								}
								else if(map["key"] =="interval")
									$scope.schedulerData[map["key"].split(/(?=[A-Z])/).join(" ")] = map.label==null?map.value +" minutes":map.label;
								else
									$scope.schedulerData[map["key"].split(/(?=[A-Z])/).join(" ")] = map.label==null?map.value:map.label;
							}
							break;
						case "incidentConfig":
							if(priorityMapping.indexOf(map["key"])>=0){
								priority.forEach(function(priorityVal){
									if(priorityVal.value == map.value)
									$scope.incidentConfigData[map["key"].split(/(?=[A-Z])/).join(" ")] = priorityVal.name;
								});												 
							}											 
							else
							$scope.incidentConfigData[map["key"].split(/(?=[A-Z])/).join(" ")] =  map.label==null?map.value:map.label;
							break;
						case "getCount":
							label.push(map.key);
							graphData.push(map.value);
							break;
					}
				});
			}
			else
			{
				toastr.error("something went wrong.","error");
			}
			$scope.$apply();
			$j('#loader').hide();
			var ctx = document.getElementById('incidentChart').getContext('2d');
			ctx.setLineDash([5, 10]);

			// Draw a dashed line
			ctx.beginPath();
			ctx.moveTo(0, 0);
			ctx.lineTo(100, 100);
			ctx.stroke();
			var myChart = new Chart(ctx, {
				type: 'line',
				data: {
					labels:label,
					datasets: [{
						label: 'Incident created per day ',
						data:graphData,
						backgroundColor: [
							'rgba(173,255,47,0.2)',
							'rgba(255,140,0,0.2)',
							'rgba(0,191,255,0.2)',
							'rgba(255,20,147,0.2)',
							'rgba(255,255,0,0.2)',
							'rgba(176,196,222,0.2)',
							'rgba(64,224,208,0.2)'
						],
						borderColor: [
							'rgba(173,255,47,1)',
							'rgba(255,140,0,1)',
							'rgba(0,191,255,1)',
							'rgba(255,20,147,1)',
							'rgba(255,255,0,1)',
							'rgba(176,196,222,1)',
							'rgba(64,224,208,1)'
						],
						borderWidth: 1
					}]
				},
				options: {
					elements: {
						line: {
							tension: 0, // disables bezier curves
							fill: false
						}
					},
					legend: {
						display: true,
						text: 'Incident created in last 7 days'
					},
					scales: {
						xAxes: [{
							ticks: {
								maxRotation: 90,
								minRotation: 50
							}
						}],
						yAxes: [{
							ticks: {
								beginAtZero: true
							}
						}]
					}
				}
			});
		}

	};
	//call getCount() of DruvaEngine
	var getCount = new GlideAjax("DruvaEngine");
	getCount.addParam("sysparm_name","getCount");
	getCount.getXML($scope.onload);
});
